function e(){let e=new Date;return{year:e.getFullYear(),month:e.getMonth()+1}}function t(e=new Date){return`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,`0`)}-${String(e.getDate()).padStart(2,`0`)}`}function n(e){return new Date(e.year,e.month-1,1).toLocaleDateString(`ru-RU`,{month:`long`,year:`numeric`})}function r(e,t){let n=new Date(e.year,e.month-1+t,1);return{year:n.getFullYear(),month:n.getMonth()+1}}function i(e){let t=new Date(e.year,e.month-1,1),n=new Date(e.year,e.month,0).getDate(),r=(t.getDay()+6)%7,i=[];for(let e=0;e<r;e+=1)i.push(null);for(let t=1;t<=n;t+=1){let n=`${e.year}-${String(e.month).padStart(2,`0`)}-${String(t).padStart(2,`0`)}`;i.push({key:n,day:t,dateKey:n})}return i}function a(e){if(!e)return`не активна`;let t=new Date(e);return Number.isNaN(t.getTime())?e:t.toLocaleDateString(`ru-RU`,{day:`2-digit`,month:`2-digit`,year:`numeric`})}function o(e){let[t,n,r]=e.split(`-`).map(Number);return new Date(t,n-1,r).toLocaleDateString(`ru-RU`,{weekday:`short`,day:`2-digit`,month:`short`})}function s(e,t){let[n,r]=e.split(`:`).map(Number),i=(n*60+r+t)%1440;return`${e}–${String(Math.floor(i/60)).padStart(2,`0`)}:${String(i%60).padStart(2,`0`)}`}export{e as a,r as c,a as i,o as n,t as o,s as r,n as s,i as t};